sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        var requestData = request.body.data;
        var grtrade, current_trd,
            allSuccessFlag = true,
            allErrFlag = true,
			return400Flag = true,
			respBody = {},    
            failureDescription, createEventForWidgetFailure;

        respBody.success = {};
        respBody.success.messageIds = [];
        respBody.failure = [];

        var limit = gs.getProperty('x_hsb11_hsbc_mss_o.EquitiesInboundPayloadSize');
        var encodeObj = gs.base64Encode(JSON.stringify(requestData));
        var size = (encodeObj.length) * 3 / 4;
        if (size > limit) {
			failureDescription = 'HSBC MSS iQube Equities Event Inbound batch processing failure in scripted rest api el_inbound_event/batch - Unable to serve request because the request payload is more than ' + limit / 1000 + ' KB';
            createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('MAJOR', failureDescription, 'MSSiQubeEquities_EventInbound');
            response.setStatus(413);
            respBody.status = 'Unable to serve request because the request payload is more than ' + limit / 1000 + ' KB';
            response.setBody(respBody);
            return;
        }

        //Need to check if the below is required and what should be the limit if required 
        if (requestData.length > 50) {
			failureDescription = 'HSBC MSS iQube Equities Event Inbound batch processing failure in scripted rest api el_inbound_event/batch - Too many elements in the array (<50)';
            createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('MAJOR', failureDescription, 'MSSiQubeEquities_EventInbound');
			response.setStatus(413);
            respBody.status = 'Too many elements in the array (<50)';
            response.setBody(respBody);
            return;
        }

        for (var i = 0; i < requestData.length; i++) {
            current_trd = requestData[i].HEADER;
            //Technical UUID - Unique event ID for every single event - SN will use this to identify duplicate events
            if (current_trd.messageid == '' || current_trd.messageid == undefined) {
				respBody.failure.push({"messageId": current_trd.messageid.toString(), "errorMessage": "Rejected due to missing MessageID"});
                allSuccessFlag = false;
                allErrFlag = false;

                gs.error('Equities Event Inbound batch processing failure in scripted rest api el_inbound_event/batch - lack of message ID from EventLayer, event messageid: ' + current_trd.messageid + ', objectid: ' + current_trd.objectid + ', eventstatus: ' + current_trd.eventstatus);
            } else if (current_trd.eventtype == '' || current_trd.eventtype == undefined) {
                respBody.failure.push({"messageId": current_trd.messageid.toString(), "errorMessage": "Rejected due to missing EventType"});
                allSuccessFlag = false;

                gs.error('Equities Event Inbound batch processing failure in scripted rest api el_inbound_event/batch - lack of Event Type from EventLayer, event messageid: ' + current_trd.messageid + ', objectid: ' + current_trd.objectid + ', eventstatus: ' + current_trd.eventstatus);
            } else if (current_trd.source == '' || current_trd.source == undefined) {
				respBody.failure.push({"messageId": current_trd.messageid.toString(), "errorMessage": "Rejected due to missing Source"});
                allSuccessFlag = false;
                allErrFlag = false;

                gs.error('Equities Event Inbound batch processing failure in scripted rest api el_inbound_event/batch - lack of Source from EventLayer, event messageid: ' + current_trd.messageid + ', objectid: ' + current_trd.objectid + ', eventstatus: ' + current_trd.eventstatus);
            } else if (current_trd.objecttype == '' || current_trd.objecttype == undefined) {
				respBody.failure.push({"messageId": current_trd.messageid.toString(), "errorMessage": "Rejected due to missing ObjectType"});
                allSuccessFlag = false;
                allErrFlag = false;

                gs.error('Equities Event Inbound batch processing failure in scripted rest api el_inbound_event/batch - lack of Object Type from EventLayer, event messageid: ' + current_trd.messageid + ', objectid: ' + current_trd.objectid + ', eventstatus: ' + current_trd.eventstatus);
            } else if (current_trd.objectidtype == '' || current_trd.objectidtype == undefined) {
				respBody.failure.push({"messageId": current_trd.messageid.toString(), "errorMessage": "Rejected due to missing ObjectIDType"});
                allSuccessFlag = false;
                allErrFlag = false;

                gs.error('Equities Event Inbound batch processing failure in scripted rest api el_inbound_event/batch - lack of ObjectID Type from EventLayer, event messageid: ' + current_trd.messageid + ', objectid: ' + current_trd.objectid + ', eventstatus: ' + current_trd.eventstatus);
            } else if (current_trd.objectversion == '' || current_trd.objectversion == undefined) {
				respBody.failure.push({"messageId": current_trd.messageid.toString(), "errorMessage": "Rejected due to missing ObjectVersion"});
                allSuccessFlag = false;
                allErrFlag = false;

                gs.error('Equities Event Inbound batch processing failure in scripted rest api el_inbound_event/batch - lack of Object Version from EventLayer, event messageid: ' + current_trd.messageid + ', objectid: ' + current_trd.objectid + ', eventstatus: ' + current_trd.eventstatus);
            } else if (current_trd.eventstatus == '' || current_trd.eventstatus == undefined) {
				respBody.failure.push({"messageId": current_trd.messageid.toString(), "errorMessage": "Rejected due to missing EventStatus"});
                allSuccessFlag = false;
                allErrFlag = false;

                gs.error('Equities Event Inbound batch processing failure in scripted rest api el_inbound_event/batch - lack of Event Status from EventLayer, event messageid: ' + current_trd.messageid + ', objectid: ' + current_trd.objectid + ', eventstatus: ' + current_trd.eventstatus);
            } else if (current_trd.eventdatetime == '' || current_trd.eventdatetime == undefined) {
				respBody.failure.push({"messageId": current_trd.messageid.toString(), "errorMessage": "Rejected due to missing EventDateTime"});
                allSuccessFlag = false;
                allErrFlag = false;

                gs.error('Equities Event Inbound batch processing failure in scripted rest api el_inbound_event/batch - lack of Event Datetime from EventLayer, event messageid: ' + current_trd.messageid + ', objectid: ' + current_trd.objectid + ', eventstatus: ' + current_trd.eventstatus);
            } else if (current_trd.objectid == '' || current_trd.objectid == undefined) {
				respBody.failure.push({"messageId": current_trd.messageid.toString(), "errorMessage": "Rejected due to missing ObjectID"});
                allSuccessFlag = false;
                allErrFlag = false;

                gs.error('Equities Event Inbound batch processing failure in scripted rest api el_inbound_event/batch - lack of objectID from EventLayer, event messageid: ' + current_trd.messageid + ', objectid: ' + current_trd.objectid + ', eventstatus: ' + current_trd.eventstatus);
            } else {
                var grEvent = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_inbound');
                grEvent.addQuery('messageid', current_trd.messageid);
                grEvent.addQuery('source', current_trd.source);
                grEvent.query();
                if (grEvent.next()) {  //Check whether duplicated event
					respBody.failure.push({"messageId": current_trd.messageid.toString(), "errorMessage": "Rejected due to having a duplicated event"});
                    allSuccessFlag = false;
					allErrFlag = false;
                } else {
					return400Flag = false;
                    grEvent = new GlideRecord('x_hsb11_hsbc_mss_o_mss_event_inbound');
                    grEvent.initialize();

                    //Mapping to corresponding fields from Header part to Inbound staging table
					grEvent.objectid = current_trd.objectid;
                    grEvent.objectversion = current_trd.objectversion;
                    grEvent.objecttype = current_trd.objecttype;
                    grEvent.objectidtype = current_trd.objectidtype;
                    grEvent.eventstatus = current_trd.eventstatus;
                    grEvent.eventdatetime = current_trd.eventdatetime;
                    grEvent.eventdatetime_integer = new GlideDateTime(current_trd.eventdatetime).getNumericValue();
                    grEvent.source = current_trd.source;
                    grEvent.messageid = current_trd.messageid;
                    grEvent.eventtype = current_trd.eventtype;
                    grEvent.additional_attributes = current_trd.additionalattributes;
                    var queueid = setQueue(current_trd.objectid);
                    if (!isNaN(queueid))
                        grEvent.queue = parseInt(queueid).toString();

                    if (!grEvent.insert()) {
                        gs.error('Equities Event Inbound batch processing - record insert failed in scripted rest api el_inbound_event/batch, event messageid: ' + current_trd.messageid + ', objectid: ' + current_trd.objectid + ', eventstatus: ' + current_trd.eventstatus);
						respBody.failure.push({"messageId": current_trd.messageid.toString(), "errorMessage": "Event Record Not Inserted Properly"});
						allSuccessFlag = false;
                    } else {
						respBody.success.messageIds.push(current_trd.messageid.toString());
						allErrFlag = false;
                    }
                }
            }
        }

        if (allErrFlag == true) {  //All event records in the batch failed to be proceeded
			failureDescription = "HSBC MSS iQube Equities unexpected error from Event Inbound scripted rest api el_inbound_event/batch - Failed to proceed a whole batch due to some internal errors in iQube, please refer to details: " + JSON.stringify(respBody.failure);
            createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('MAJOR', failureDescription, 'MSSiQubeEquities_EventInbound');

			response.setStatus(500);
            respBody.status = 'All the event records failed to be proceeded in a batch';
		} else if (allSuccessFlag == true) {  //All event records in the batch are proceeded successfully
			response.setStatus(200);
            respBody.status = 'All the event records have been successfully processed in a batch';
		} else if (return400Flag == true) {  //All event records in the batch are duplicated or lack of value(s) like: messageid/eventtype/source/objecttype/objectidtype/objectversion/eventstatus/eventdatetime/objectid
			failureDescription = "HSBC MSS iQube Equities unexpected error from Event Inbound scripted rest api el_inbound_event/batch - Failed to proceed a whole batch since all the event records are duplicated or lack of value(s) like: messageid/eventtype/source/objecttype/objectidtype/objectversion/eventstatus/eventdatetime/objectid in the batch, please refer to details: " + JSON.stringify(respBody.failure);
            createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('MAJOR', failureDescription, 'MSSiQubeEquities_EventInbound');

			response.setStatus(400);
            respBody.status = 'All the event records are duplicated or lack of value(s) like: messageid/eventtype/source/objecttype/objectidtype/objectversion/eventstatus/eventdatetime/objectid in a batch';
		} else {
			response.setStatus(207);  //Partial success - 207, need to return response body with agreed format to EL
		}

        response.setBody(respBody);
    } catch (exp) {
        gs.error("Equities Event Inbound batch processing failure - Unexpected error from scripted rest api el_inbound_event/batch, Name: " + exp.name + ", Message: " + exp.message);
        failureDescription = "HSBC MSS iQube Equities unexpected error from Event Inbound scripted rest api el_inbound_event/batch, Name: " + exp.name + ", Message: " + exp.message;
        createEventForWidgetFailure = new x_hsb11_hsbc_mss_t.hsbcWidgetFailureHandler().createITIDEvent('MAJOR', failureDescription, 'MSSiQubeEquities_EventInbound');
        response.setStatus(500);
        response.setBody({
            'errorMessage': 'unexpected error Name: ' + exp.name + ', Message: ' + exp.message,
            'status': 'failure'
        });
    }

    function setQueue(objId) {
        var reg = new RegExp("^[0-9]{11}"); //Regex to find first 11 digits at the start of the string
        var objInt = Number(objId.toString().match(reg));
        var queue = (objInt % 24) + 1;
        return queue;
    }

})(request, response);
